17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.rest.error.CityOwnerLimitExceededException;
34	import org.springframework.samples.petclinic.rest.error.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.rest.error.DisposableEmailDomainException;
36	import org.springframework.samples.petclinic.rest.error.DuplicateOwnerException;
37	import org.springframework.samples.petclinic.rest.error.FutureRegistrationDateException;
38	import org.springframework.samples.petclinic.rest.error.InvalidEmailException;
39	import org.springframework.samples.petclinic.rest.error.InvalidPostcodeException;
40	import org.springframework.samples.petclinic.rest.error.InvalidTelephoneException;
41	import org.springframework.samples.petclinic.rest.error.RequiredFieldsMissingException;
42	import org.springframework.security.access.AccessDeniedException;
43	import org.springframework.validation.BindingResult;
44	import org.springframework.web.bind.MethodArgumentNotValidException;
45	import org.springframework.web.bind.annotation.ControllerAdvice;
46	import org.springframework.web.bind.annotation.ExceptionHandler;
47	import org.springframework.web.bind.annotation.ResponseBody;
48	
49	/**
50	 * Global Exception handler for REST controllers.
51	 * <p>
52	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
53	 *
54	 * @author Vitaliy Fedoriv
55	 * @author Alexander Dudkin
56	 */
57	@ControllerAdvice
58	public class ExceptionControllerAdvice {
59	
60	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
61	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
62	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
63	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
64	
65	    /**
66	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
67	     * class.
68	     *
69	     * @param e     Object referring to the thrown exception.
70	     * @param status HTTP response status.
71	     * @param url URL request.
72	     */
73	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
74	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
75	        problemDetail.setType(URI.create(url.toString()));
76	        problemDetail.setTitle(e.getClass().getSimpleName());
77	        problemDetail.setDetail(detail);
78	        problemDetail.setProperty("timestamp", Instant.now());
79	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
80	        return problemDetail;
81	    }
82	
83	    /**
84	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
85	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
86	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
87	     * would catch it and report an authorization failure as a 500.
88	     *
89	     * @param e The {@link AccessDeniedException} to propagate
90	     * @throws AccessDeniedException always
91	     */
92	    @ExceptionHandler(AccessDeniedException.class)
93	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
94	        throw e;
95	    }
96	
97	    /**
98	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
99	     *
100	     * @param e The {@link Exception} to be handled
101	     * @param request {@link HttpServletRequest} object referring to the current request.
102	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
103	     */
104	    @ExceptionHandler(Exception.class)
105	    @ResponseBody
106	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
107	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
108	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
109	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
110	        return ResponseEntity.status(status).body(detail);
111	    }
112	
113	    /**
114	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
115	     * method returns a 404 Not Found status if an entity does not exist.
116	     *
117	     * @param e The {@link DataIntegrityViolationException} to be handled
118	     * @param request {@link HttpServletRequest} object referring to the current request.
119	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
120	     */
121	    @ExceptionHandler(DataIntegrityViolationException.class)
122	    @ResponseBody
123	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
124	        logger.warn("Data integrity violation at {} {}: {}",
125	            request.getMethod(),
126	            request.getRequestURI(),
127	            e.getMessage());
128	        logger.debug("Data integrity violation stacktrace", e);
129	        HttpStatus status = HttpStatus.NOT_FOUND;
130	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
131	        return ResponseEntity.status(status).body(detail);
132	    }
133	
134	    /**
135	     * Handles exception thrown by Bean Validation on controller methods parameters
136	     *
137	     * @param e The {@link MethodArgumentNotValidException} to be handled
138	     * @param request {@link HttpServletRequest} object referring to the current request.
139	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
140	     */
141	    @ExceptionHandler(MethodArgumentNotValidException.class)
142	    @ResponseBody
143	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
144	        HttpStatus status = HttpStatus.BAD_REQUEST;
145	        BindingErrorsResponse errors = new BindingErrorsResponse();
146	        BindingResult bindingResult = e.getBindingResult();
147	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
148	        if (bindingResult.hasErrors()) {
149	            errors.addAllErrors(bindingResult);
150	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
151	                .map(fieldError -> fieldError.getField())
152	                .distinct()
153	                .toList();
154	            detail.setProperty("errors", invalidFields);
155	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
156	                .map(fieldError -> {
157	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
158	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
159	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
160	                        fieldError.getField(),
161	                        defaultMessage,
162	                        rejectedValue);
163	                    return new ValidationMessageDto(message)
164	                        .putAdditionalProperty("field", fieldError.getField())
165	                        .putAdditionalProperty("rejectedValue", rejectedValue)
166	                        .putAdditionalProperty("defaultMessage", defaultMessage);
167	                })
168	                .toList();
169	            logger.debug("Validation error at {} {}: {}",
170	                request.getMethod(),
171	                request.getRequestURI(),
172	                bindingResult.getFieldErrors());
173	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
174	            return ResponseEntity.status(status).body(detail);
175	        }
176	        return ResponseEntity.status(status).body(detail);
177	    }
178	
179	    /**
180	     * Handles {@link RequiredFieldsMissingException} thrown when a request omits or leaves blank a
181	     * mandatory field. Returns a 400 Bad Request whose {@code errors} array names each missing field.
182	     *
183	     * @param e The {@link RequiredFieldsMissingException} to be handled
184	     * @param request {@link HttpServletRequest} object referring to the current request.
185	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
186	     */
187	    @ExceptionHandler(RequiredFieldsMissingException.class)
188	    @ResponseBody
189	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
190	        logger.debug("Missing required fields at {} {}: {}",
191	            request.getMethod(),
192	            request.getRequestURI(),
193	            e.getMissingFields());
194	        HttpStatus status = HttpStatus.BAD_REQUEST;
195	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
196	        detail.setProperty("errors", e.getMissingFields());
197	        return ResponseEntity.status(status).body(detail);
198	    }
199	
200	    /**
201	     * Handles {@link InvalidTelephoneException} thrown when a submitted telephone number does not
202	     * contain exactly ten digits once every non-digit character has been stripped. Returns a
203	     * 400 Bad Request naming the offending field.
204	     *
205	     * @param e The {@link InvalidTelephoneException} to be handled
206	     * @param request {@link HttpServletRequest} object referring to the current request.
207	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
208	     */
209	    @ExceptionHandler(InvalidTelephoneException.class)
210	    @ResponseBody
211	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
212	        logger.debug("Invalid telephone at {} {}: {}",
213	            request.getMethod(),
214	            request.getRequestURI(),
215	            e.getRejectedValue());
216	        HttpStatus status = HttpStatus.BAD_REQUEST;
217	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
218	        detail.setProperty("errors", List.of("telephone"));
219	        return ResponseEntity.status(status).body(detail);
220	    }
221	
222	    /**
223	     * Handles {@link InvalidEmailException} thrown when a submitted email address is present but not
224	     * a syntactically valid address. Returns a 400 Bad Request naming the offending field.
225	     *
226	     * @param e The {@link InvalidEmailException} to be handled
227	     * @param request {@link HttpServletRequest} object referring to the current request.
228	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
229	     */
230	    @ExceptionHandler(InvalidEmailException.class)
231	    @ResponseBody
232	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
233	        logger.debug("Invalid email at {} {}: {}",
234	            request.getMethod(),
235	            request.getRequestURI(),
236	            e.getRejectedValue());
237	        HttpStatus status = HttpStatus.BAD_REQUEST;
238	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
239	        detail.setProperty("errors", List.of("email"));
240	        return ResponseEntity.status(status).body(detail);
241	    }
242	
243	    /**
244	     * Handles {@link DisposableEmailDomainException} thrown when a submitted email address belongs to
245	     * a disposable-email domain on the blocklist. Returns a 400 Bad Request naming the offending field.
246	     *
247	     * @param e The {@link DisposableEmailDomainException} to be handled
248	     * @param request {@link HttpServletRequest} object referring to the current request.
249	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
250	     */
251	    @ExceptionHandler(DisposableEmailDomainException.class)
252	    @ResponseBody
253	    public ResponseEntity<ProblemDetail> handleDisposableEmailDomainException(DisposableEmailDomainException e, HttpServletRequest request) {
254	        logger.debug("Disposable email domain at {} {}: {}",
255	            request.getMethod(),
256	            request.getRequestURI(),
257	            e.getRejectedValue());
258	        HttpStatus status = HttpStatus.BAD_REQUEST;
259	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
260	        detail.setProperty("errors", List.of("email"));
261	        return ResponseEntity.status(status).body(detail);
262	    }
263	
264	    /**
265	     * Handles {@link InvalidPostcodeException} thrown when a submitted postcode is present but is
266	     * not a 4-digit code, or is out of range for the region of the owner's city. Returns a
267	     * 400 Bad Request naming the offending field.
268	     *
269	     * @param e The {@link InvalidPostcodeException} to be handled
270	     * @param request {@link HttpServletRequest} object referring to the current request.
271	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
272	     */
273	    @ExceptionHandler(InvalidPostcodeException.class)
274	    @ResponseBody
275	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
276	        logger.debug("Invalid postcode at {} {}: {}",
277	            request.getMethod(),
278	            request.getRequestURI(),
279	            e.getRejectedValue());
280	        HttpStatus status = HttpStatus.BAD_REQUEST;
281	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
282	        detail.setProperty("errors", List.of("postcode"));
283	        return ResponseEntity.status(status).body(detail);
284	    }
285	
286	    /**
287	     * Handles {@link DuplicateOwnerException} thrown when an owner is created whose whole identity
288	     * key (normalized telephone, email and household id) matches that of an existing owner. Returns
289	     * a 409 Conflict naming the offending field.
290	     *
291	     * @param e The {@link DuplicateOwnerException} to be handled
292	     * @param request {@link HttpServletRequest} object referring to the current request.
293	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
294	     */
295	    @ExceptionHandler(DuplicateOwnerException.class)
296	    @ResponseBody
297	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerException(DuplicateOwnerException e, HttpServletRequest request) {
298	        logger.debug("Duplicate owner at {} {}: {}",
299	            request.getMethod(),
300	            request.getRequestURI(),
301	            e.getIdentityKey());
302	        HttpStatus status = HttpStatus.CONFLICT;
303	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
304	        detail.setProperty("errors", List.of("identityKey"));
305	        return ResponseEntity.status(status).body(detail);
306	    }
307	
308	    /**
309	     * Handles {@link CityOwnerLimitExceededException} thrown when an owner is created in a city that
310	     * already contains the maximum permitted number of owners. Returns a 409 Conflict naming the
311	     * offending field.
312	     *
313	     * @param e The {@link CityOwnerLimitExceededException} to be handled
314	     * @param request {@link HttpServletRequest} object referring to the current request.
315	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
316	     */
317	    @ExceptionHandler(CityOwnerLimitExceededException.class)
318	    @ResponseBody
319	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitExceededException(CityOwnerLimitExceededException e, HttpServletRequest request) {
320	        logger.debug("City owner limit exceeded at {} {}: {}",
321	            request.getMethod(),
322	            request.getRequestURI(),
323	            e.getCity());
324	        HttpStatus status = HttpStatus.CONFLICT;
325	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
326	        detail.setProperty("errors", List.of("city"));
327	        return ResponseEntity.status(status).body(detail);
328	    }
329	
330	    /**
331	     * Handles {@link FutureRegistrationDateException} thrown when an owner is created with a supplied
332	     * registration date later than the server's current date. Returns a 400 Bad Request naming the
333	     * offending field.
334	     *
335	     * @param e The {@link FutureRegistrationDateException} to be handled
336	     * @param request {@link HttpServletRequest} object referring to the current request.
337	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
338	     */
339	    @ExceptionHandler(FutureRegistrationDateException.class)
340	    @ResponseBody
341	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
342	        logger.debug("Future registration date at {} {}: {}",
343	            request.getMethod(),
344	            request.getRequestURI(),
345	            e.getRegistrationDate());
346	        HttpStatus status = HttpStatus.BAD_REQUEST;
347	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
348	        detail.setProperty("errors", List.of("registrationDate"));
349	        return ResponseEntity.status(status).body(detail);
350	    }
351	
352	    /**
353	     * Handles {@link DailyOwnerLimitExceededException} thrown when an owner is created on a day that
354	     * has already reached the maximum permitted number of owner registrations. Returns a 429 Too
355	     * Many Requests.
356	     *
357	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
358	     * @param request {@link HttpServletRequest} object referring to the current request.
359	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
360	     */
361	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
362	    @ResponseBody
363	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
364	        logger.debug("Daily owner limit exceeded at {} {}: {}",
365	            request.getMethod(),
366	            request.getRequestURI(),
367	            e.getRegistrationDate());
368	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
369	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
370	        return ResponseEntity.status(status).body(detail);
371	    }
372	
373	}
